def _secret(name, default=None):
    try:
        return st.secrets.get(name, default)
    except Exception:
        return default


def app_password_configurada():
    return bool(_secret("app_password"))


def acceso_autorizado():
    expected = _secret("app_password")
    if not expected:
        return True
    if st.session_state.get("authenticated"):
        return True
    st.title("S&S Group · Gestión Administrativa")
    st.subheader("Acceso privado")
    password = st.text_input("Contraseña", type="password")
    if st.button("Ingresar", type="primary"):
        if password == expected:
            st.session_state["authenticated"] = True
            st.rerun()
        else:
            st.error("Contraseña incorrecta.")
    return False


if not acceso_autorizado():
    st.stop()

def get_conn():
    database_url = _secret("database_url") or _secret("DATABASE_URL")
    if database_url:
        if psycopg is None:
            st.error("Falta instalar psycopg para conectar con Supabase.")
            st.stop()
        return PostgresCompatConnection(psycopg.connect(database_url, row_factory=dict_row))
    conn = sqlite3.connect(
        DB_PATH,
        check_same_thread=False,
        timeout=30
    )
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL;")
    conn.execute("PRAGMA busy_timeout = 30000;")
    return conn


def _pg_sql(sql):
    """Convierte los marcadores SQLite usados por la app al formato de PostgreSQL."""
    return sql.replace("?", "%s")


class PostgresCompatCursor:
    def __init__(self, cursor):
        self._cursor = cursor
        self.lastrowid = None

    def execute(self, sql, params=()):
        statement = _pg_sql(sql)
        self._cursor.execute(statement, params)
        if "RETURNING" in statement.upper():
            row = self._cursor.fetchone()
            if row:
                self.lastrowid = row.get("id") if isinstance(row, dict) else row[0]
        return self

    def fetchone(self):
        return self._cursor.fetchone()

    def fetchall(self):
        return self._cursor.fetchall()

    def __iter__(self):
        return iter(self._cursor)


class PostgresCompatConnection:
    """Capa mínima para mantener el SQL existente mientras los datos viven en Supabase."""
    is_postgres = True

    def __init__(self, connection):
        self._connection = connection

    def cursor(self):
        return PostgresCompatCursor(self._connection.cursor())

    def execute(self, sql, params=()):
        cur = self.cursor()
        return cur.execute(sql, params)

    def executemany(self, sql, params_seq):
        cur = self._connection.cursor()
        cur.executemany(_pg_sql(sql), params_seq)
        return PostgresCompatCursor(cur)

    def executescript(self, script):
        self._connection.execute(script)

    def commit(self):
        self._connection.commit()

    def rollback(self):
        self._connection.rollback()

    def close(self):
        self._connection.close()


DBIntegrityError = (sqlite3.IntegrityError, PostgresIntegrityError)

def init_db():
    conn = get_conn()
    cur = conn.cursor()
    if getattr(conn, "is_postgres", False):
        cur.execute("""
        CREATE TABLE IF NOT EXISTS emisores(
            id BIGSERIAL PRIMARY KEY, nombre TEXT NOT NULL, cuit TEXT NOT NULL UNIQUE,
            condicion_iva TEXT, punto_venta INTEGER DEFAULT 1, activo INTEGER DEFAULT 1,
            observaciones TEXT
        )""")
        cur.execute("""
        CREATE TABLE IF NOT EXISTS items_facturacion(
            id BIGSERIAL PRIMARY KEY, nombre TEXT NOT NULL, descripcion TEXT NOT NULL,
            precio_sugerido NUMERIC DEFAULT 0, activo INTEGER DEFAULT 1
        )""")
        cur.execute("""
        CREATE TABLE IF NOT EXISTS comprobantes_arca(
            id BIGSERIAL PRIMARY KEY, cliente_id BIGINT NOT NULL REFERENCES clientes(id),
            fecha_emision DATE NOT NULL, periodo_desde DATE, periodo_hasta DATE,
            periodo_texto TEXT, tipo_periodo TEXT, tipo_comprobante TEXT DEFAULT 'C',
            punto_venta INTEGER DEFAULT 1, numero_comprobante INTEGER, cae TEXT,
            vencimiento_cae DATE, estado_arca TEXT DEFAULT 'BORRADOR', total NUMERIC NOT NULL DEFAULT 0,
            observaciones TEXT, creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        cur.execute("""
        CREATE TABLE IF NOT EXISTS comprobante_items(
            id BIGSERIAL PRIMARY KEY, comprobante_id BIGINT NOT NULL REFERENCES comprobantes_arca(id),
            item_catalogo_id BIGINT, descripcion TEXT NOT NULL, cantidad NUMERIC DEFAULT 1,
            precio_unitario NUMERIC DEFAULT 0, subtotal NUMERIC DEFAULT 0
        )""")
        cur.execute("""
        CREATE TABLE IF NOT EXISTS email_log(
            id BIGSERIAL PRIMARY KEY, comprobante_id BIGINT, cliente_id BIGINT NOT NULL,
            destinatario TEXT NOT NULL, asunto TEXT NOT NULL, estado TEXT NOT NULL,
            detalle TEXT, fecha_hora TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")
        cur.execute("CREATE TABLE IF NOT EXISTS app_meta(clave TEXT PRIMARY KEY, valor TEXT)")
        cur.execute("""
        CREATE TABLE IF NOT EXISTS archivos_pdf(
            id BIGSERIAL PRIMARY KEY, nombre TEXT NOT NULL, contenido BYTEA NOT NULL,
            mime_type TEXT DEFAULT 'application/pdf', creado_en TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )""")

        # La primera versión del esquema usaba booleanos; la app histórica trabaja con 0/1.
        for table, column in (("clientes", "activo"),):
            cur.execute(f"""
                DO $$ BEGIN
                    IF EXISTS (
                        SELECT 1 FROM information_schema.columns
                        WHERE table_schema='public' AND table_name='{table}'
                          AND column_name='{column}' AND data_type='boolean'
                    ) THEN
                        ALTER TABLE {table} ALTER COLUMN {column} DROP DEFAULT;
                        ALTER TABLE {table} ALTER COLUMN {column} TYPE INTEGER
                        USING CASE WHEN {column} THEN 1 ELSE 0 END;
                        ALTER TABLE {table} ALTER COLUMN {column} SET DEFAULT 1;
                    END IF;
                END $$
            """)

        def add_pg_col(table, name, definition):
            cur.execute(f"ALTER TABLE {table} ADD COLUMN IF NOT EXISTS {name} {definition}")

        for name, definition in (
            ("emisor_predeterminado_id", "BIGINT"), ("email_facturacion", "TEXT"),
            ("envio_automatico_factura", "INTEGER DEFAULT 1"), ("tipo_cliente", "TEXT DEFAULT 'Mensual'"),
            ("domicilio", "TEXT"), ("condicion_iva_receptor_id", "INTEGER"),
            ("condicion_iva_receptor_desc", "TEXT")
        ):
            add_pg_col("clientes", name, definition)
        for name, definition in (
            ("emisor_id", "BIGINT"), ("pdf_path", "TEXT"), ("pdf_archivo_id", "BIGINT"),
            ("email_enviado", "INTEGER DEFAULT 0"), ("email_enviado_a", "TEXT"),
            ("email_enviado_en", "TIMESTAMPTZ"), ("email_error", "TEXT"),
            ("cbte_tipo_codigo", "INTEGER"), ("imp_neto", "NUMERIC"), ("imp_iva", "NUMERIC"),
            ("fecha_vto_pago", "DATE"), ("arca_observaciones", "TEXT"), ("arca_error", "TEXT")
        ):
            add_pg_col("comprobantes_arca", name, definition)
        add_pg_col("movimientos", "pdf_archivo_id", "BIGINT")
        for name, definition in (
            ("domicilio_fiscal", "TEXT"), ("ingresos_brutos", "TEXT"),
            ("inicio_actividades", "DATE"), ("regimen_iva", "TEXT"),
            ("iva_alicuota", "NUMERIC DEFAULT 21"),
            ("ambiente_arca", "TEXT DEFAULT 'HOMOLOGACION'"),
            ("precios_incluyen_iva", "INTEGER DEFAULT 1")
        ):
            add_pg_col("emisores", name, definition)
        cur.execute("UPDATE clientes SET tipo_cliente='Mensual' WHERE tipo_cliente IS NULL OR TRIM(tipo_cliente)='' ")
        conn.commit()
        conn.close()
        return

    cur.executescript("""
    CREATE TABLE IF NOT EXISTS emisores(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nombre TEXT NOT NULL,
        cuit TEXT NOT NULL UNIQUE,
        condicion_iva TEXT,
        punto_venta INTEGER DEFAULT 1,
        activo INTEGER DEFAULT 1,
        observaciones TEXT
    );

    CREATE TABLE IF NOT EXISTS clientes(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nombre TEXT NOT NULL UNIQUE,
        cuit TEXT,
        modalidad TEXT NOT NULL DEFAULT 'Factura',
        honorario REAL DEFAULT 0,
        vigente_desde TEXT,
        dia_generacion INTEGER DEFAULT 1,
        activo INTEGER DEFAULT 1,
        observaciones TEXT
    );

    CREATE TABLE IF NOT EXISTS honorarios(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cliente_id INTEGER NOT NULL,
        vigente_desde TEXT NOT NULL,
        honorario REAL NOT NULL,
        nota TEXT,
        FOREIGN KEY(cliente_id) REFERENCES clientes(id)
    );

    CREATE TABLE IF NOT EXISTS movimientos(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        fecha TEXT NOT NULL,
        cliente_id INTEGER NOT NULL,
        tipo TEXT NOT NULL,
        descripcion TEXT,
        importe REAL NOT NULL,
        periodo TEXT,
        comprobante TEXT,
        pdf_path TEXT,
        estado_conciliacion TEXT,
        creado_en TEXT NOT NULL,
        UNIQUE(cliente_id, tipo, periodo, comprobante),
        FOREIGN KEY(cliente_id) REFERENCES clientes(id)
    );

    CREATE TABLE IF NOT EXISTS items_facturacion(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nombre TEXT NOT NULL,
        descripcion TEXT NOT NULL,
        precio_sugerido REAL DEFAULT 0,
        activo INTEGER DEFAULT 1
    );

    CREATE TABLE IF NOT EXISTS comprobantes_arca(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cliente_id INTEGER NOT NULL,
        fecha_emision TEXT NOT NULL,
        periodo_desde TEXT,
        periodo_hasta TEXT,
        periodo_texto TEXT,
        tipo_periodo TEXT,
        tipo_comprobante TEXT DEFAULT 'C',
        punto_venta INTEGER DEFAULT 1,
        numero_comprobante INTEGER,
        cae TEXT,
        vencimiento_cae TEXT,
        estado_arca TEXT DEFAULT 'BORRADOR',
        total REAL NOT NULL DEFAULT 0,
        observaciones TEXT,
        creado_en TEXT NOT NULL,
        FOREIGN KEY(cliente_id) REFERENCES clientes(id)
    );

    CREATE TABLE IF NOT EXISTS comprobante_items(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        comprobante_id INTEGER NOT NULL,
        item_catalogo_id INTEGER,
        descripcion TEXT NOT NULL,
        cantidad REAL DEFAULT 1,
        precio_unitario REAL DEFAULT 0,
        subtotal REAL DEFAULT 0,
        FOREIGN KEY(comprobante_id) REFERENCES comprobantes_arca(id)
    );
    """)
    # Migraciones simples para bases existentes
    cols_clientes = [r["name"] for r in conn.execute("PRAGMA table_info(clientes)").fetchall()]
    if "emisor_predeterminado_id" not in cols_clientes:
        conn.execute("ALTER TABLE clientes ADD COLUMN emisor_predeterminado_id INTEGER")

    cols_comp = [r["name"] for r in conn.execute("PRAGMA table_info(comprobantes_arca)").fetchall()]
    if "emisor_id" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN emisor_id INTEGER")

    cols_clientes = [r["name"] for r in conn.execute("PRAGMA table_info(clientes)").fetchall()]
    if "email_facturacion" not in cols_clientes:
        conn.execute("ALTER TABLE clientes ADD COLUMN email_facturacion TEXT")
    if "envio_automatico_factura" not in cols_clientes:
        conn.execute("ALTER TABLE clientes ADD COLUMN envio_automatico_factura INTEGER DEFAULT 1")

    cols_comp = [r["name"] for r in conn.execute("PRAGMA table_info(comprobantes_arca)").fetchall()]
    if "pdf_path" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN pdf_path TEXT")
    if "pdf_archivo_id" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN pdf_archivo_id INTEGER")
    if "email_enviado" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN email_enviado INTEGER DEFAULT 0")
    if "email_enviado_a" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN email_enviado_a TEXT")
    if "email_enviado_en" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN email_enviado_en TEXT")
    if "email_error" not in cols_comp:
        conn.execute("ALTER TABLE comprobantes_arca ADD COLUMN email_error TEXT")

    cols_mov = [r["name"] for r in conn.execute("PRAGMA table_info(movimientos)").fetchall()]
    if "pdf_archivo_id" not in cols_mov:
        conn.execute("ALTER TABLE movimientos ADD COLUMN pdf_archivo_id INTEGER")

    conn.execute("""
        CREATE TABLE IF NOT EXISTS archivos_pdf(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nombre TEXT NOT NULL,
            contenido BLOB NOT NULL,
            mime_type TEXT DEFAULT 'application/pdf',
            creado_en TEXT NOT NULL
        )
    """)

    conn.execute("""
        CREATE TABLE IF NOT EXISTS email_log(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            comprobante_id INTEGER,
            cliente_id INTEGER NOT NULL,
            destinatario TEXT NOT NULL,
            asunto TEXT NOT NULL,
            estado TEXT NOT NULL,
            detalle TEXT,
            fecha_hora TEXT NOT NULL,
            FOREIGN KEY(comprobante_id) REFERENCES comprobantes_arca(id),
            FOREIGN KEY(cliente_id) REFERENCES clientes(id)
        )
    """)

    def add_col(table, name, definition):
        cols = [r["name"] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()]
        if name not in cols:
            conn.execute(f"ALTER TABLE {table} ADD COLUMN {name} {definition}")

    # Datos fiscales del emisor
    add_col("emisores", "domicilio_fiscal", "TEXT")
    add_col("emisores", "ingresos_brutos", "TEXT")
    add_col("emisores", "inicio_actividades", "TEXT")
    add_col("emisores", "regimen_iva", "TEXT")
    add_col("emisores", "iva_alicuota", "REAL DEFAULT 21")
    add_col("emisores", "ambiente_arca", "TEXT DEFAULT 'HOMOLOGACION'")
    add_col("emisores", "precios_incluyen_iva", "INTEGER DEFAULT 1")

    # Clasificación administrativa del cliente
    # Mensual: forma parte de la cartera recurrente. Ocasional: trabajos/facturas aisladas.
    add_col("clientes", "tipo_cliente", "TEXT DEFAULT 'Mensual'")
    conn.execute("UPDATE clientes SET tipo_cliente='Mensual' WHERE tipo_cliente IS NULL OR TRIM(tipo_cliente)='' ")

    # Datos fiscales del receptor
    add_col("clientes", "domicilio", "TEXT")
    add_col("clientes", "condicion_iva_receptor_id", "INTEGER")
    add_col("clientes", "condicion_iva_receptor_desc", "TEXT")

    # Resultado fiscal del comprobante
    add_col("comprobantes_arca", "cbte_tipo_codigo", "INTEGER")
    add_col("comprobantes_arca", "imp_neto", "REAL")
    add_col("comprobantes_arca", "imp_iva", "REAL")
    add_col("comprobantes_arca", "fecha_vto_pago", "TEXT")
    add_col("comprobantes_arca", "arca_observaciones", "TEXT")
    add_col("comprobantes_arca", "arca_error", "TEXT")

    conn.commit()
    conn.close()

def query_df(sql, params=()):
    conn = get_conn()
    if getattr(conn, "is_postgres", False):
        cur = conn.execute(sql, params)
        rows = cur.fetchall()
        df = pd.DataFrame(rows)
    else:
        df = pd.read_sql_query(sql, conn, params=params)
    conn.close()
    return df

def execute(sql, params=()):
    conn = get_conn()
    cur = conn.cursor()
    if getattr(conn, "is_postgres", False) and re.match(r"^\s*INSERT\b", sql, re.I) and "RETURNING" not in sql.upper():
        sql = sql.rstrip().rstrip(";") + " RETURNING id"
    cur.execute(sql, params)
    conn.commit()
    rid = cur.lastrowid
    conn.close()
    return rid


def guardar_pdf_permanente(nombre, contenido):
    """Guarda un PDF dentro de PostgreSQL/Supabase y devuelve su identificador."""
    if not contenido:
        return None
    if not (_secret("database_url") or _secret("DATABASE_URL")):
        return None
    return execute(
        "INSERT INTO archivos_pdf(nombre,contenido,mime_type,creado_en) VALUES(?,?,?,?)",
        (nombre, bytes(contenido), "application/pdf", datetime.now().isoformat())
    )


def leer_pdf_permanente(pdf_archivo_id=None, pdf_path=None):
    if pdf_archivo_id and not pd.isna(pdf_archivo_id):
        conn = get_conn()
        row = conn.execute("SELECT nombre,contenido FROM archivos_pdf WHERE id=?", (int(pdf_archivo_id),)).fetchone()
        conn.close()
        if row:
            return bytes(row["contenido"]), str(row["nombre"])
    path = str(pdf_path or "").strip()
    if path and Path(path).exists():
        return Path(path).read_bytes(), Path(path).name
    return None, None

def money(v):
    try:
        return f"$ {float(v):,.0f}".replace(",", ".")
    except:
        return "$ 0"

def get_clientes(active_only=True):
    where = "WHERE activo=1" if active_only else ""
    return query_df(f"SELECT * FROM clientes {where} ORDER BY nombre")


